CREATE TRIGGER RefVessel_Version_Create
	ON RefVessel
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RV_PK, 'RV'
	FROM inserted
GO
CREATE TRIGGER RefVessel_Version_Update
	ON RefVessel
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RV_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefVessel_DataChangeHistory
	ON RefVessel
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RV_PK, 'RV' FROM inserted
	UNION
	SELECT RV_PK, 'RV' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefVessel_DataProcessingResult_Delete
	ON RefVessel
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RV_PK
	END
